package dev.morphe.vm.exception.internal.scope;

/**
 * Thrown when an invalid variable slot identifier is used.
 *
 * <p>
 * Variable slots are assigned by the compiler and are expected to be
 * non-negative integers. This exception is raised when an operation
 * attempts to access or declare a slot with an invalid identifier.
 * </p>
 *
 * <p>
 * In a correctly generated bytecode program, this exception typically
 * indicates a compiler bug, malformed bytecode, or corruption of
 * execution state.
 * </p>
 */
public final class InvalidVariableSlotException extends ScopeException {

  /**
   * Creates an exception for an invalid variable slot.
   *
   * @param slot the invalid slot identifier
   */
  public InvalidVariableSlotException(int slot) {
    super("Invalid variable slot: %d", slot);
  }
}